import {openDB,read,save} from './storage.js';
import {miles,reimbursement,mikeReport,mapsURL,csvCell,validateBackup,validateOdometers,CUSTOMER_MESSAGE,seattleAddress,scheduledInstant,scheduledStats,periodRange} from './domain.js';
let state,tab='shift',busy=false,range=periodRange('weekly'),reportView='weekly',settingsEditing=false;
const $=s=>document.querySelector(s),id=()=>crypto.randomUUID(),now=()=>new Date().toISOString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Date(t).toLocaleDateString([], {month:'short',day:'numeric',year:'numeric'}),time=t=>new Date(t).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});
const localInput=t=>{const d=new Date(t);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const localDate=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const active=()=>state.shifts.find(s=>s.status==='active'),currentRun=()=>state.runs.find(r=>r.status==='active');
const bag='<path d="M6 7h12l-1 3 2 11H5L7 10zM6 7l2-4h8l2 4M7 10h10M8 3l2 4m6-4-2 4"/>';
const icons={shift:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',deliveries:bag,history:'<path d="M4 5v5h5M4 10a8 8 0 1 1 1 8M12 7v5l4 2"/>',reports:'<path d="M5 21V11m7 10V4m7 17v-7"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="m9 3 1-1h4l1 3 3 1 3 3-1 3 1 3-3 3-3 1-1 3h-4l-1-3-3-1-3-3 1-3-1-3 3-3z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]}</svg>`;
function notify(t){$('#notice').textContent=t;setTimeout(()=>$('#notice').textContent='',5000);}
function dialog(title,body,submit,label='Save'){const d=$('#modal');d.innerHTML=`<form><h2>${title}</h2>${body}<p class="error" role="alert"></p><div class="actions"><button type="button" data-close>Cancel</button>${submit?`<button class="primary" type="submit">${label}</button>`:''}</div></form>`;d.querySelector('[data-close]').onclick=()=>d.close();if(submit)d.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=d.querySelector('[type=submit]');btn.disabled=true;try{const form=e.target;await submit(new FormData(form));if(d.querySelector('form')===form)d.close();}catch(err){d.querySelector('.error').textContent=err.message;}finally{btn.disabled=false;}};d.showModal();}
async function mutate(fn){if(busy)throw Error('Please wait for the previous save.');busy=true;const next=structuredClone(state);try{fn(next);await save(next);state=next;render();}finally{busy=false;}}
function audit(s,entityId,action,before,after){s.audit.push({id:id(),entityId,action,before,after,at:now()});}
function header(title,description,action=''){return `<div class="heading-row"><div><h1>${title}</h1><div class="muted">${description}</div></div>${action}</div>`;}
function metric(label,value,detail){return `<div class="metric"><div class="muted">${label}</div><div class="number">${value}</div><small>${detail}</small></div>`;}
function deliveriesFor(s){return state.deliveries.filter(d=>d.shiftId===s.id);}
function deliveryCard(d,i){return `<div class="card delivery"><span class="stop">${i+1}</span><div class="content"><div class="row"><h3>${esc(d.name||'Delivery')}</h3><span class="badge ${d.scheduledAt?'scheduled':''}">${d.status==='delivered'?'Delivered':d.scheduledAt?'Scheduled':'Standard'}</span></div><div class="address">${esc(d.address)}</div>${d.scheduledAt?`<p class="muted">Requested arrival · ${date(d.scheduledAt)}, ${time(d.scheduledAt)}</p>`:''}${d.completedAt?`<p class="muted">Delivered · ${time(d.completedAt)}</p>`:''}${d.ticket?`<div class="muted">Ticket ${esc(d.ticket)}</div>`:''}<div class="actions">${d.status==='delivered'?`<button data-action="undo" data-id="${d.id}">Undo delivered</button>`:`<button class="primary" data-action="delivered" data-id="${d.id}">Delivered</button><button data-action="navigate" data-id="${d.id}">Navigate</button>`}<button data-action="message" data-id="${d.id}" ${!d.phone?'disabled':''}>Message</button>${d.status==='ready'?`<button class="link" data-action="edit" data-id="${d.id}">Edit</button><button class="link" data-action="cancel" data-id="${d.id}">Remove</button>`:''}</div></div></div>`;}
function shiftView(){const s=active(),done=s?deliveriesFor(s).filter(d=>d.status==='delivered').length:0,run=currentRun(),ready=s?deliveriesFor(s).filter(d=>d.status==='ready'):[];return header('Your shift, in order.','A little less juggling. A smoother delivery night.')+`<section class="hero"><div><div class="eyebrow">${s?'ON THE CLOCK':'READY WHEN YOU ARE'}</div><h2>${s?'Have a good shift.':'A fresh start for every shift.'}</h2><p>${s?`Started at ${time(s.startedAt)} · Odometer ${s.startOdometer.toLocaleString()} mi. Your records stay on this device.`:'Start with your odometer reading. We’ll keep your deliveries and mileage together, from the first bag to the last stop.'}</p><div class="actions"><button class="primary" data-action="${s?'add':'start'}">${s?'+ Add delivery':'Start shift →'}</button>${s?'<button class="outline" data-action="end">End shift</button>':''}</div></div>${icon('deliveries')}</section><div class="metrics">${metric('Deliveries completed',done,s?'This shift':'Your next shift awaits')}${metric('Delivery runs',s?state.runs.filter(r=>r.shiftId===s.id).length:0,'Out and back again')}${metric('Starting odometer',s?s.startOdometer.toLocaleString():'—','Actual miles at shift end')}</div><div class="grid-two"><section><div class="section-head"><h2>${run?'Out for delivery':'Ready for delivery'}</h2><span class="badge">${run?run.deliveryIds.filter(x=>state.deliveries.find(d=>d.id===x)?.status!=='delivered').length:ready.length} orders</span></div>${run?`<div class="card"><h3>Your current run</h3><p class="muted">Started ${time(run.startedAt)} · ${run.deliveryIds.length} delivery stops</p><div class="actions"><button data-action="deliveries">View deliveries</button><button class="primary" data-action="return">Back at restaurant</button></div></div>`:ready.length?ready.slice(0,3).map(deliveryCard).join('')+`<button class="primary" data-action="route">Prepare route →</button>`:`<div class="card empty">${icon('deliveries')}<h3>No bags on the counter yet.</h3><p class="muted">Add each prepared order here when you pick it up. One order or a whole batch—we’ll keep it organized.</p><button class="outline" data-action="${s?'add':'start'}">${s?'Add your first delivery':'Start your first shift'}</button></div>`}</section><aside><div class="section-head"><h2>A note for the road</h2></div><div class="card"><div class="eyebrow">YOUR MILEAGE, ACCURATELY</div><h3>The odometer tells the story.</h3><p class="muted">Start and end readings give you actual shift mileage—including the drive back to the restaurant.</p><hr style="border:0;border-top:1px solid #e2e4d9;margin:20px 0"><div class="private">◌ PRIVATE BY DESIGN</div><p class="muted">Your reimbursement calculations stay in your reports. Mike receives actual miles, without the private numbers.</p></div></aside></div><p class="welcome-note">Made for the rhythm of your delivery night.</p>`;}
function deliveriesView(){const s=active(),ds=s?deliveriesFor(s).filter(d=>d.status!=='canceled'):[];return header('The delivery counter.','Prepared bags, planned stops, and one less thing to remember.',s?'<button class="primary" data-action="add">+ Add delivery</button>':'')+`<div class="hint">Routes use your chosen stop order. Automatic optimization and road-mile estimates are not connected yet.</div>${ds.length?ds.map(deliveryCard).join(''):`<div class="card empty">${icon('deliveries')}<h3>${s?'Your counter is clear.':'Start a shift to add deliveries.'}</h3><p class="muted">Only delivery orders belong here. Scheduled customer pickups stay with the restaurant.</p></div>`}${s&&ds.some(d=>d.status==='ready')&&!currentRun()?'<button class="primary" data-action="route">Prepare route →</button>':''}`;}
function historyView(){const ss=state.shifts.filter(s=>s.status==='finalized').sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt));return header('Every shift, kept.','Your delivery records, whenever you need them.')+(ss.length?`<div class="card table-wrap history-list"><table><thead><tr><th>Date</th><th>Shift time</th><th>Miles</th><th>Deliveries</th><th>Actions</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${date(s.startedAt)}</td><td>${time(s.startedAt)} – ${localDate(s.startedAt)!==localDate(s.endedAt)?date(s.endedAt)+' ':''}${time(s.endedAt)}</td><td>${miles(s)}</td><td>${deliveriesFor(s).filter(d=>d.status==='delivered').length}</td><td><div class="row"><button class="compact" data-action="report" data-id="${s.id}">Send report</button><button class="compact outline" data-action="correct" data-id="${s.id}">Edit</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty"><h3>Your first shift starts the story.</h3><p class="muted">Completed shifts will appear here, with actual mileage and a report you can prepare again.</p></div>');}
const filtered=()=>state.shifts.filter(s=>s.status==='finalized'&&(!range.from||localDate(s.startedAt)>=range.from)&&(!range.to||localDate(s.startedAt)<=range.to));
function reportsView(){const ss=filtered(),total=ss.reduce((a,s)=>a+miles(s),0),paid=ss.filter(s=>s.rate!=null);return header('Your numbers. Your records.','A private view of your mileage and expected reimbursement.')+`<div class="card"><div class="form-grid"><div><label for="from">From date</label><input id="from" type="date" value="${range.from}"></div><div><label for="to">Through date</label><input id="to" type="date" value="${range.to}"></div></div><div class="actions"><button data-action="filter">Apply date range</button><button data-action="export" class="primary">Export CSV</button></div><p class="muted">Shifts are grouped by their local start date. Customer information is excluded.</p></div><div class="period-switch" role="group" aria-label="Report view">${['weekly','monthly','yearly'].map(v=>`<button data-period="${v}" aria-pressed="${reportView===v}" class="${reportView===v?'primary':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}${reportView==='custom'?'<span class="muted">Custom dates</span>':''}</div><div class="metrics">${metric('Actual miles',Number(total.toFixed(3)),`${ss.length} completed shifts`)}${metric('Completed deliveries',ss.reduce((a,s)=>a+deliveriesFor(s).filter(d=>d.status==='delivered').length,0),'In selected shifts')}${metric('Expected reimbursement','$'+paid.reduce((a,s)=>a+reimbursement(s),0).toFixed(2),paid.length===ss.length?'Private · configured rate':`${ss.length-paid.length} shifts have no rate`)}</div><div class="hint">Estimated road miles are unavailable until a routing data source is chosen. Missing estimates are not treated as zero.</div><div class="card"><h2>Scheduled delivery timing</h2>${(()=>{const ds=ss.flatMap(s=>deliveriesFor(s)),stats=scheduledStats(ds);return `<h3>${stats.onTime} / ${stats.total} delivered by requested time</h3><p class="muted">Provisional rule: at or before the requested time counts as on time; no grace period. We can change this once you choose a window.</p>${ds.filter(d=>d.scheduledAt&&d.status==='delivered').map(d=>`<div class="timing-row"><span>${date(d.scheduledAt)} · requested ${time(d.scheduledAt)}</span><span>${d.completedAt?'Delivered '+time(d.completedAt):'Completion time unavailable'}</span></div>`).join('')}`;})()}</div><div class="card table-wrap"><table><thead><tr><th>Shift</th><th>Actual miles</th><th>Rate / mi</th><th>Expected</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${date(s.startedAt)}</td><td>${miles(s)}</td><td>${s.rate==null?'—':'$'+s.rate.toFixed(2)}</td><td>${reimbursement(s)==null?'—':'$'+reimbursement(s).toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="4">No completed shifts in this date range.</td></tr>'}</tbody></table></div>`;}
function settingsView(){return header('Make it yours.','A few details to make every shift easier.')+`${settingsEditing?`<form id="settings-form" class="card"><div class="row"><h2>The essentials</h2><button type="button" data-action="settings-cancel">Cancel</button></div><label for="restaurant">Restaurant address</label><input id="restaurant" name="restaurant" value="${esc(state.settings.restaurant)}" placeholder="Street address, city, state"><label for="mike">Mike’s phone number</label><input id="mike" name="mike" type="tel" value="${esc(state.settings.mike)}" placeholder="Enter privately on this device"><label for="rate">Private reimbursement rate ($ per mile)</label><input id="rate" name="rate" type="number" min="0" step="0.001" value="${state.settings.rate??''}" placeholder="Your employer’s agreed rate"><p class="muted">No legal rate is assumed. Changes apply to new shifts; previous shifts keep their original rate.</p><button class="primary" type="submit">Save settings</button><p class="error" role="alert"></p></form>`:`<div class="card"><div class="row"><h2>The essentials</h2><button data-action="settings-edit">Edit</button></div><dl class="essentials"><dt>Restaurant address</dt><dd>${esc(state.settings.restaurant||'Not set')}</dd><dt>Mike’s phone number</dt><dd>${esc(state.settings.mike||'Not set — enter once using Edit')}</dd><dt>Private reimbursement rate</dt><dd>${state.settings.rate==null?'Not set':'$'+state.settings.rate.toFixed(3)+' per mile'}</dd></dl><p class="muted">Saved on this device. Mike’s number is reused for every report.</p></div>`}<div class="card"><h2>Keep a copy.</h2><p class="muted">Records live in this browser’s local database. They can be lost if storage is cleared or your device is lost. Save a backup in Files or iCloud Drive regularly.</p><div class="actions"><button data-action="backup" class="primary">Download full backup</button><button data-action="restore">Restore backup</button></div><p class="muted">Full backups contain saved customer details. Keep them private.</p><input type="file" id="restore-file" accept="application/json,.json" hidden></div><div class="card"><h2>Saved customers</h2><p class="muted">${state.customers.length} customer records on this device. Removing a customer also redacts their historical contact details while retaining shift totals.</p>${state.customers.map(c=>`<div class="row"><span>${esc(c.name)}</span><button class="link" data-action="delete-customer" data-id="${c.id}">Delete customer</button></div>`).join('')}</div><div class="hint">Local preview · v0.2.0<br>iPhone installation, Maps stop limits, and Messages handoff still need testing on your phone. This computer’s localhost address cannot be opened directly on an iPhone.</div>`;}
function render(){const names={shift:'Shift',deliveries:'Deliveries',history:'History',reports:'Reports',settings:'Settings'};$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>Delivery Manager<small>ONE SHIFT AT A TIME</small></div></div><nav class="nav" aria-label="Main navigation">${Object.entries(names).map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}" ${tab===k?'aria-current="page"':''}>${icon(k)}${v}</button>`).join('')}</nav><footer>LOCAL RECORDS. CLEAR MIND.<br>Your night, a little more organized.<br>Version 0.2 · Your workflow, refined</footer></aside><main class="main"><div class="topline"><span>${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</span><span class="status">${navigator.onLine?'Saved on this device':'Offline · local records'}</span></div>${({shift:shiftView,deliveries:deliveriesView,history:historyView,reports:reportsView,settings:settingsView}[tab])()}</main></div>`;document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{reportView=b.dataset.period;range=periodRange(reportView);render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action,b.dataset.id).catch(e=>notify(e.message)));if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=f.get('rate');settingsEditing=false;await mutate(s=>s.settings={restaurant:f.get('restaurant').trim(),mike:f.get('mike').trim(),rate:r===''?null:Number(r)});notify('Settings saved on this device.');}catch(err){notify(err.message);}};if($('#restore-file'))$('#restore-file').onchange=restoreFile;}
function addDelivery(existing){if(!active())return;dialog(existing?'Edit delivery':'Add a delivery',`<label for="customer">Customer name</label><input id="customer" name="name" value="${esc(existing?.name||'')}" autocomplete="off" placeholder="Start typing a repeat customer"><div class="suggestions" id="suggestions"></div><label for="address">Delivery address (include unit)</label><input id="address" name="address" required value="${esc(existing?.address||'')}" placeholder="Street address and unit — Seattle, WA"><label for="phone">Customer phone</label><input id="phone" name="phone" type="tel" value="${esc(existing?.phone||'')}" placeholder="Optional — needed for a text"><div><label for="ticket">Ticket number</label><input id="ticket" name="ticket" value="${esc(existing?.ticket||'')}"></div><label class="checkbox-label"><input id="scheduled-toggle" name="isScheduled" type="checkbox" ${existing?.scheduledAt?'checked':''}> Scheduled Delivery?</label><div id="scheduled-fields" ${existing?.scheduledAt?'':'hidden'}><label for="scheduled">Requested delivery time</label><select id="scheduled" name="scheduled">${Array.from({length:48},(_,i)=>{const h=Math.floor(i/2),m=i%2?30:0,value=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');const requested=existing?.scheduledAt?new Date(existing.scheduledAt):new Date();const selected=existing?.scheduledAt?requested.getHours()===h&&requested.getMinutes()===m:Math.ceil((requested.getHours()*60+requested.getMinutes())/30)*30%1440===h*60+m;return `<option value="${value}" ${selected?'selected':''}>${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}</option>`;}).join('')}</select><p class="muted">Uses the shift start date: ${date(active().startedAt)}.</p></div><label><input name="remember" type="checkbox" checked style="width:auto;min-height:auto;margin-right:7px"> Save details for future local suggestions</label><p class="muted">Maps will receive the destination when you navigate. No customer directory is uploaded.</p>`,async f=>{await mutate(s=>{const details={name:f.get('name').trim(),address:f.get('address').trim(),phone:f.get('phone').trim(),ticket:f.get('ticket').trim(),scheduledAt:f.get('isScheduled')?scheduledInstant(active().startedAt,f.get('scheduled')):null};if(!details.address)throw Error('Enter a delivery address.');let customerId=existing?.customerId||null;if(f.get('remember')){const c=s.customers.find(c=>c.address===details.address&&c.phone===details.phone&&c.name===details.name);customerId=c?.id||id();if(!c)s.customers.push({id:customerId,name:details.name,address:details.address,phone:details.phone});}if(existing){const d=s.deliveries.find(d=>d.id===existing.id);audit(s,d.id,'edit',structuredClone(d),details);Object.assign(d,details,{customerId});}else s.deliveries.push({id:id(),shiftId:active().id,customerId,...details,status:'ready',enteredAt:now()});});notify('Delivery saved.');},existing?'Save changes':'Add delivery');$('#scheduled-toggle').onchange=e=>{$('#scheduled-fields').hidden=!e.target.checked;};$('#customer').oninput=e=>{const q=e.target.value.toLowerCase();const hits=q?state.customers.filter(c=>[c.name,c.address,c.phone].some(v=>v.toLowerCase().includes(q))).slice(0,4):[];$('#suggestions').innerHTML=hits.map(c=>`<button type="button" data-customer="${c.id}">${esc(c.name)} · ${esc(c.address)}</button>`).join('');$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=state.customers.find(c=>c.id===b.dataset.customer);$('#customer').value=c.name;$('#address').value=c.address;$('#phone').value=c.phone;$('#suggestions').innerHTML='';});};}
function phoneURL(phone){const p=phone.replace(/[\s().-]/g,'');if(!/^\+?\d{7,15}$/.test(p))throw Error('Enter a valid phone number first.');return 'sms:'+p;}
function compose(phone,text,title){const url=phoneURL(phone);dialog(title,`<p class="muted">Review, copy, then open Messages. Paste the text and tap Send there.</p><label for="message-text">Message</label><textarea id="message-text">${esc(text)}</textarea><div class="actions"><button type="button" id="copy-message">Copy text</button><a class="primary" style="padding:13px;border-radius:12px;text-decoration:none" href="${esc(url)}">Open Messages</a></div><p class="muted">Recipient: ${esc(phone)}. Opening Messages does not confirm a text was sent.</p>`,null);$('#copy-message').onclick=async()=>{try{await navigator.clipboard.writeText($('#message-text').value);$('#copy-message').textContent='Copied ✓';}catch{$('#message-text').select();notify('Copy is unavailable. Select and copy the text manually.');}};}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(){download(`delivery-manager-backup-${localDate(now())}.json`,JSON.stringify({format:'delivery-manager',version:1,exportedAt:now(),data:state},null,2),'application/json');notify('Backup downloaded. Store it somewhere safe.');}
async function restoreFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>20e6)throw Error('Backup is too large (maximum 20 MB).');const restored=validateBackup(JSON.parse(await file.text()));dialog('Replace local records?',`<p>This backup contains ${restored.shifts.length} shifts, ${restored.deliveries.length} deliveries, and ${restored.customers.length} customers.</p><p class="muted">This replaces all current records. Download a current backup before continuing.</p><button type="button" id="prebackup">Download current backup</button>`,async()=>{await mutate(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,restored);});notify('Backup restored.');},'Replace and restore');$('#prebackup').onclick=backup;}catch(err){notify(err.message);}}
async function handle(action,key){const s=active(),d=state.deliveries.find(d=>d.id===key);if(action==='settings-edit'){settingsEditing=true;return render();}if(action==='settings-cancel'){settingsEditing=false;return render();}if(action==='start')return dialog('Start your shift',`<p class="muted">Enter the odometer reading before you begin driving.</p>${(()=>{const last=state.shifts.filter(x=>x.status==='finalized').sort((a,b)=>Date.parse(b.endedAt)-Date.parse(a.endedAt))[0];return last?`<div class="hint">Last shift ended at <strong>${last.endOdometer.toLocaleString()} mi</strong> on ${date(last.endedAt)}. Reference only—enter your current reading below.</div>`:'';})()}<label for="start">Starting odometer (miles)</label><input id="start" name="start" type="number" min="0" step="0.001" inputmode="decimal" required autofocus>`,async f=>{await mutate(v=>{if(v.shifts.some(x=>x.status==='active'))throw Error('A shift is already active.');v.shifts.push({id:id(),status:'active',startedAt:now(),startOdometer:Number(f.get('start')),rate:v.settings.rate,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone});});notify('Shift started. Have a good night.');},'Start shift');if(action==='add')return addDelivery();if(action==='edit')return addDelivery(d);if(action==='deliveries'){tab='deliveries';return render();}if(action==='cancel')return dialog('Remove this delivery?',`<p>${esc(d.name)} · ${esc(d.address)}</p><label>Reason</label><input name="reason" required>`,async f=>mutate(v=>{const x=v.deliveries.find(x=>x.id===key);audit(v,key,'cancel',x.status,f.get('reason'));x.status='canceled';}),'Remove');if(action==='delivered')return dialog('Ready to mark delivered?',`<p><strong>${esc(d.name||'This delivery')}</strong></p><p class="muted">${esc(d.address)}</p><p>This records the delivery time. You can prepare the customer’s text next.</p>`,async()=>{await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);if(x.status==='delivered')return;audit(v,key,'delivered',x.status,'delivered');x.status='delivered';x.completedAt=now();});if(d.phone)compose(d.phone,CUSTOMER_MESSAGE,'Delivery completed');else notify('Marked delivered. Undo is available on the delivery card.');},'Yes, delivered');if(action==='undo'){if(!s||d.shiftId!==s.id)throw Error('Use History for changes to a finalized shift.');await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);audit(v,key,'undo delivery',x.completedAt,null);x.status=v.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(key))?'active':'ready';delete x.completedAt;});return notify('Delivery completion undone. Any text already sent cannot be recalled.');}if(action==='message')return compose(d.phone,CUSTOMER_MESSAGE,'Message customer');if(action==='navigate'){const u=new URL('https://maps.apple.com/directions');u.searchParams.set('destination',seattleAddress(d.address));u.searchParams.set('mode','driving');window.location.href=u.href;return;}if(action==='route'){if(!state.settings.restaurant){tab='settings';render();return notify('Add the restaurant address first.');}let stops=state.deliveries.filter(d=>d.shiftId===s.id&&d.status==='ready');dialog('Choose your stop order',`<p class="muted">Manual ordering for this first build. The restaurant return is included. Road-mile estimates are unavailable.</p><div id="stop-order"></div>`,async()=>{await mutate(v=>{if(v.runs.some(r=>r.status==='active'))throw Error('Finish the current run first.');const ids=stops.map(d=>d.id);v.runs.push({id:id(),shiftId:s.id,deliveryIds:ids,status:'active',startedAt:now(),estimateStatus:'unavailable'});v.deliveries.filter(d=>ids.includes(d.id)).forEach(d=>d.status='active');});dialog('Your route is saved',`<p class="muted">${stops.length} deliveries, then back to the restaurant. Check the stop order in Maps before driving. If Maps cannot accept the entire route, navigate to each delivery from its card.</p><a href="${esc(mapsURL(stops.map(x=>seattleAddress(x.address)),seattleAddress(state.settings.restaurant)))}">Open route in Apple Maps →</a>`,null);},'Save run');const draw=()=>{$('#stop-order').innerHTML=stops.map((d,i)=>`<div class="card"><div class="row"><span>${i+1}. ${esc(d.name||d.address)}</span><div><button type="button" data-up="${i}" aria-label="Move stop up" ${i===0?'disabled':''}>↑</button><button type="button" data-down="${i}" aria-label="Move stop down" ${i===stops.length-1?'disabled':''}>↓</button></div></div><small>${esc(d.address)}</small></div>`).join('');$('#stop-order').querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=b.dataset.up!=null?i-1:i+1;[stops[i],stops[j]]=[stops[j],stops[i]];draw();});};draw();return;}if(action==='return'){const r=currentRun();if(r.deliveryIds.some(id=>state.deliveries.find(d=>d.id===id)?.status!=='delivered'))throw Error('Complete the remaining deliveries before closing this run.');await mutate(v=>{const x=v.runs.find(x=>x.id===r.id);x.status='returned';x.returnedAt=now();});return notify('Run complete. Back at the restaurant.');}if(action==='end'){if(currentRun()||state.deliveries.some(d=>d.shiftId===s.id&&['ready','active'].includes(d.status)))throw Error('Complete or remove pending deliveries and close the current run first.');return dialog('Finish your shift',`<p class="muted">Starting odometer: ${s.startOdometer} mi. Actual mileage is used for your records and Mike’s report.</p><label for="end">Ending odometer (miles)</label><input id="end" name="end" type="number" min="${s.startOdometer}" step="0.001" inputmode="decimal" required>`,async f=>{const end=Number(f.get('end'));validateOdometers(s.startOdometer,end);await mutate(v=>{const x=v.shifts.find(x=>x.id===s.id);x.endOdometer=end;x.endedAt=now();x.status='finalized';});tab='history';render();notify('Shift saved. Your report is ready to prepare.');},'Save completed shift');}if(action==='report'){const shift=state.shifts.find(x=>x.id===key);if(!state.settings.mike){tab='settings';render();return notify('Save Mike’s phone number first.');}return compose(state.settings.mike,mikeReport(shift,state.deliveries,state.runs),'Mike’s shift report');}if(action==='correct'){const x=state.shifts.find(x=>x.id===key);return dialog('Edit shift',`<p class="muted">The original readings are retained in the correction log.</p><label>Starting reading</label><input name="start" type="number" min="0" step="0.001" required value="${x.startOdometer}"><label>Ending reading</label><input name="end" type="number" min="0" step="0.001" required value="${x.endOdometer}"><label for="shift-start">Shift start date and time</label><input id="shift-start" name="startedAt" type="datetime-local" required value="${localInput(x.startedAt)}"><label for="shift-end">Shift end date and time</label><input id="shift-end" name="endedAt" type="datetime-local" required value="${localInput(x.endedAt)}"><label>Reason for correction</label><input name="reason" required>`,async f=>{const a=Number(f.get('start')),b=Number(f.get('end'));validateOdometers(a,b);const startedAt=new Date(f.get('startedAt')).toISOString(),endedAt=new Date(f.get('endedAt')).toISOString();if(Date.parse(endedAt)<Date.parse(startedAt))throw Error('Shift end must be after its start.');await mutate(v=>{const z=v.shifts.find(z=>z.id===key);audit(v,key,'shift correction', {start:z.startOdometer,end:z.endOdometer,startedAt:z.startedAt,endedAt:z.endedAt},{start:a,end:b,startedAt,endedAt,reason:f.get('reason')});z.startOdometer=a;z.endOdometer=b;z.startedAt=startedAt;z.endedAt=endedAt;});},'Save');}if(action==='filter'){const from=$('#from').value,to=$('#to').value;if(from&&to&&from>to)throw Error('Choose an end date on or after the start date.');range={from,to};reportView='custom';return render();}if(action==='export'){const rows=[['shift_id','shift_date','time_zone','started_at','ended_at','start_odometer_mi','end_odometer_mi','actual_miles','estimated_miles','estimate_status','deliveries_completed','delivery_runs','rate_per_mile','expected_reimbursement','scheduled_completed','delivered_by_requested_time','timing_rule'],...filtered().map(s=>[s.id,localDate(s.startedAt),s.timeZone,s.startedAt,s.endedAt,s.startOdometer,s.endOdometer,miles(s),'','unavailable',deliveriesFor(s).filter(d=>d.status==='delivered').length,state.runs.filter(r=>r.shiftId===s.id).length,s.rate,reimbursement(s),scheduledStats(deliveriesFor(s)).total,scheduledStats(deliveriesFor(s)).onTime,'at or before requested time; provisional'])];return download(`delivery-records-${localDate(now())}.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}if(action==='backup')return backup();if(action==='restore')return $('#restore-file').click();if(action==='delete-customer')return dialog('Delete customer details?',`<p>This removes the saved customer and redacts their name, phone, and address in past deliveries. Shift totals are kept. Previously downloaded backups are unchanged.</p>`,async()=>{await mutate(v=>{v.customers=v.customers.filter(c=>c.id!==key);v.deliveries.filter(d=>d.customerId===key).forEach(d=>{d.name='Deleted customer';d.address='Redacted';d.phone='';d.customerId=null;});v.audit=v.audit.filter(a=>!state.deliveries.some(d=>d.customerId===key&&d.id===a.entityId));});},'Delete details');}
try{await openDB();state=await read();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('#app').innerHTML='<main class="main"><h1>We couldn’t open your records.</h1><p>Local storage may be unavailable. Please reopen this app in a regular browser window. No records have been reset.</p></main>';}
window.addEventListener('online',()=>state&&render());window.addEventListener('offline',()=>state&&render());
